/**
 * Holds the guide of connect4 games.
 */
export const CONNECT4_GUIDE: Playbook =
{
    intro: `Connect4 is a two-player connection game where the objective is to be
        the first to form a horizontal, vertical, or diagonal line of four of
        one's own colored checkers in the grid.`,
    ruleset: `<ul>
                <li><b>Step 1</b>: Position the grid upright in the center of the
                layout.</li>
                <li><b>Step 2</b>: Both players select a different color for their
                checkers and collect the corresponding pieces.</li>
                <li><b>Step 3</b>: One player, usually the winner of the previous
                game, begins by dropping a checker into any available space in one
                of the grid's columns — allowing the checker to fall to the lowest
                available position in the column.</li>
                <li>
                  <b>Step 4</b>: The following player continues the game by also
                  dropping a checker into one of the available columns.
                  <ul>
                    <li>If the player connects four of their own checkers, they
                    win the game. However, if the grid fills without a winner,
                    the game ends in a draw.</li>
                  </ul>
                </li>
                <li><b>Step 5</b>: Repeat step 4 until the game ends.</li>
            </ul>`,
    scoreguide: `<ul>
                   <li><b>Loss</b>: Player receives 0 points.</li>
                   <li><b>Win</b>: Player earns 1 point.</li>
                   <li><b>Draw</b>: Players gain 0 points.</li>
                </ul>`
};

