/**
 * Holds the guide of conquer games.
 */
export const CONQUER_GUIDE: Playbook =
{
    intro: `Conquer is a card game typically played with 3 to 5 players using two
        decks — though additional decks can accommodate more players. The objective
        is to form sets of at least three of a kind or sequences of three or more
        cards in the same suit. `,
    ruleset: `<ul>
                <li><b>Step 1</b>: Shuffle the decks thoroughly to ensure a random
                distribution of cards.</li>
                <li><b>Step 2</b>: One player, usually the winner of the previous
                game, deals the shuffled cards, ensuring that each player
                recieves 13 cards while they receive 14.
                  <ul>
                    <li>Before dealing, the player to the right of the dealer
                    cuts the deck, designating the bottom portion for
                    dealing and the top portion as the draw pile.
                      <ul>
                        <li>The last card of the draw pile is placed face
                        up beneath it — visible to all players — and is
                        referred to as 'the last card'.</li>
                      </ul>
                    </li>
                    <li>Cards are dealt clockwise, starting with the player to
                    the left of the dealer.
                      <ul>
                        <li>If there aren't enough cards in the dealing
                        deck, additional cards can be drawn from the draw
                        of cards.</li>
                      </ul>
                    </li>
                  </ul>
                </li>
                <li><b>Step 3</b>: Once everyone has received their cards, the
                dealer discards one card into the discard pile.
                  <ul>
                    <li>The discard pile signals that a player's turn has ended,
                    as each player must discard one card to complete their
                    turn.
                      <ul>
                        <li>If a player discards before finishing their
                        intended action, their turn passes without completing
                        that action.</li>
                      </ul>
                    </li>
                  </ul>
                </li>
                <li><b>Step 4</b>: The player to the left of the dealer continues
                the game by drawing a card from either the draw pile or the
                discard pile.
                  <ul>
                    <li>If they choose to draw from the discard pile, they must
                    have already 'gone down'. If they haven't gone down yet,
                    they must do so before picking up any cards from the
                    discard pile.
                      <ul>
                        <li>'Going down' is an action that refers to
                        revealing qualifying sets of cards totaling at least
                        41 points (or complete suits of Kings, Queens, or
                        Jacks) in the layout, effectively reducing the number
                        of cards in one's hand.</li>
                      </ul>
                    </li>
                    <li>Additionally, 'the last card' can only be picked up if
                    the current player is about to finish the game and they
                    haven't already gone down yet.</li>
                  </ul>
                </li>
                <li><b>Step 5</b>: After drawing a card, the player must either
                finish the game or discard one of their cards.
                  <ul>
                    <li>When discarding, they cannot discard any cards that
                    could be added to revealed sets. Furthermore, cards
                    cannot be added to these sets until the current player
                    has gone down.
                      <ul>
                        <li>If the current player has already gone down,
                        they can add to ANY revealed sets.</li>
                      </ul>
                    </li>
                    <li>To finish, the player must reveal all their qualifying
                    sets in the layout and then discard one card into the
                    discard pile — this card can be ANY card.
                      <ul>
                        <li>Cards can also be added to other revealed sets
                        in the layout when finishing.</li>
                      </ul>
                    </li>
                  </ul>
                </li>
                <li><b>Step 6</b>: Repeat the process from step 4 until a player
                successfully finishes the game and it comes to an end.</li>
            </ul>`,
    scoreguide: `<ul>
                    <li><b>Loss</b>: Player receives 0 points.</li>
                    <li><b>Regular Win</b>: Player earns 1 point for a standard
                    win.</li>
                    <li><b>Joker Drop</b>: Player gains 2 points for finishing by
                    discarding a joker.</li>
                    <li><b>Bottom Draw</b>: Player receives 2 points for finishing
                    with 'the last card'.</li>
                    <li><b>Loss</b>: Player earns 3 points for finishing with both
                    'the last card' and discarding a joker.</li>
              </ul>`,
    notes: `<ul>
                <li><b>Kings, Queens & Jacks</b>: Cards are counted as 10.</li>
                <li><b>Aces</b>: Cards can be counted as either 1 or 11 (e.g., if
                not part of a grouping with other aces, they can be placed before
                a 2 or after a King of the same suit).</li>
                <li><b>Jokers</b>: Cards can be used to replace any card of a
                player's choosing.
                  <ul>
                    <li>If a player goes down with a joker in a set and the
                    card it represents isn't clearly specified, they must
                    announce what the joker represents as far as number and
                    suit is concerned. This allows other players who have
                    already gone down to replace the joker with the specified
                    card when their turn comes, effectively taking the joker
                    for themselves.</li>
                  </ul>
                </li>
            </ul>`
};

