/**
 * Holds the guide of domino games.
 */
export const DOMINO_GUIDE: Playbook =
{
    intro: `Dominoes is a classic tile-based game typically played with 4 players
        using a set of dominoes that includes tiles up to 6s. The objective is to be
        the first to play all tiles in each round until one player reaches a total
        of 100 points.`,
    ruleset: `<ul>
                <li><b>Step 1</b>: Shuffle the domino tiles face down to ensure a
                random distribution of tiles.</li>
                <li><b>Step 2</b>: Each player draws an even number of tile (e.g. 7
                tiles for games with 4 players and tiles that go up to 6s) from
                the shuffled pile.
                  <ul>
                    <li>The player with the highest-valued tile should begin the
                    round by placing the tile in the center of the layout.</li>
                  </ul>
                </li>
                <li><b>Step 3</b>: The player to the left must then match one of
                their tiles to the number of pips on either ends of the layout.
                  <ul>
                    <li>If the player cannot make a move, they may pass. However,
                    a player cannot pass strategically if they have a playable
                    tile.</li>
                  </ul>
                </li>
                <li><b>Step 4</b>: Repeat step 3 until either one player has played
                all their tiles or the round becomes blocked (i.e., no possible
                tiles can be played).
                  <ul>
                    <li>When a player plays all their tiles, they receive points
                    equal to the total number of pips on the tiles remaining
                    in their opponents' hands.
                      <ul>
                        <li>The double zero is worth 25 points if held by
                        opponents until the end of the round.</li>
                      </ul>
                    </li>
                    <li>If the round is blocked, the player with the least number
                    of pips on their remaining tiles wins.
                      <ul>
                        <li>In the event of a draw, tied players share the
                        points they would have received from their opponents.</li>
                      </ul>
                    </li>
                  </ul>
                </li>
                <li><b>Step 5</b>: Repeat the process from step 1, playing as many
                rounds as necessary, until one player totals 100 points and wins
                the game.
                  <ul>
                    <li>If a player finishes a round with the double zero, they
                    earn an automatic 100 points, and the game ends with them as
                    the winner.</li>
                  </ul>
                </li>
            </ul>`,
    scoreguide: `<ul>
                   <li>Players' scores from each round are tallied until the game
                   ends.</li>
                </ul>`
};

